import React from 'react';

interface MatrixInputProps {
    n: number;
    matrix: number[][];
    vector: number[];
    onChange: (matrix: number[][], vector: number[]) => void;
}

export const MatrixInput: React.FC<MatrixInputProps> = ({
                                                            n, matrix, vector, onChange
                                                        }) => {
    const handleMatrixChange = (i: number, j: number, value: string) => {
        const newMatrix = matrix.map(row => [...row]);
        // Если поле пустое, оставляем пустым для ввода, но в данных будет 0
        newMatrix[i][j] = value === '' ? 0 : parseFloat(value);
        onChange(newMatrix, vector);
    };

    const handleVectorChange = (i: number, value: string) => {
        const newVector = [...vector];
        newVector[i] = value === '' ? 0 : parseFloat(value);
        onChange(matrix, newVector);
    };

    // Функция для форматирования отображения значения
    const formatValue = (value: number) => {
        return value === 0 ? '' : value.toString();
    };

    return (
        <div className="space-y-6">
            <div>
                <label className="block text-sm font-medium text-gray-700 mb-3">
                    Матрица коэффициентов A:
                </label>
                <div
                    className="grid gap-2"
                    style={{ gridTemplateColumns: `repeat(${n}, minmax(80px, 1fr))` }}
                >
                    {Array.from({ length: n }).map((_, i) =>
                        Array.from({ length: n }).map((_, j) => (
                            <input
                                key={`a${i}${j}`}
                                type="number"
                                value={formatValue(matrix[i]?.[j] ?? 0)}
                                onChange={(e) => handleMatrixChange(i, j, e.target.value)}
                                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 text-center"
                                step="any"
                                placeholder={`a${i+1}${j+1}`}
                            />
                        ))
                    )}
                </div>
            </div>

            <div>
                <label className="block text-sm font-medium text-gray-700 mb-3">
                    Вектор правой части b:
                </label>
                <div
                    className="grid gap-2"
                    style={{ gridTemplateColumns: `repeat(${n}, minmax(80px, 1fr))` }}
                >
                    {Array.from({ length: n }).map((_, i) => (
                        <input
                            key={`b${i}`}
                            type="number"
                            value={formatValue(vector[i] ?? 0)}
                            onChange={(e) => handleVectorChange(i, e.target.value)}
                            className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 text-center"
                            step="any"
                            placeholder={`b${i+1}`}
                        />
                    ))}
                </div>
            </div>

            <p className="text-xs text-gray-500 italic">
                * Для ввода дробных чисел используйте точку (например: 3.14)
            </p>
        </div>
    );
};
